#!/usr/bin/env node
// @effect-diagnostics nodeBuiltinImport:off globalConsole:off -- Maintainer CLI: runs tsc and writes one generated file.
/**
 * Writes `runtime/three/<major>/runtime.d.ts`: the declarations of the shell modules a game's
 * main.js imports, generated by tsc from their JSDoc (`--allowJs --declaration`), one section per
 * module under its import path. Agents read it for the runtime's API instead of the modules'
 * source. Its header carries a hash of those modules, which a test compares, so a shell change
 * without a fresh file fails.
 *
 *   node scripts/runtime-dts.ts [major]
 */
import * as NodeChildProcess from "node:child_process";
import * as NodeFS from "node:fs";
import * as NodeOS from "node:os";
import * as NodePath from "node:path";
import * as NodeURL from "node:url";
import { RUNTIME_DTS_MODULES, runtimeDtsHash } from "../apps/server/src/game/runtimeDts.ts";

const checkout = NodePath.resolve(NodePath.dirname(NodeURL.fileURLToPath(import.meta.url)), "..");
const major = process.argv[2] ?? "1";
const runtime = NodePath.join(checkout, "apps/server/templates/runtime/three", major);
const out = NodeFS.mkdtempSync(NodePath.join(NodeOS.tmpdir(), "runtime-dts-"));
try {
  const tsc = NodePath.join(checkout, "node_modules/.bin/tsc");
  NodeChildProcess.execFileSync(
    tsc,
    [
      "--ignoreConfig",
      "--allowJs",
      "--declaration",
      "--emitDeclarationOnly",
      "--noCheck",
      "--skipLibCheck",
      "--module",
      "esnext",
      "--target",
      "es2022",
      "--moduleResolution",
      "bundler",
      "--outDir",
      out,
      ...RUNTIME_DTS_MODULES.map((name) => NodePath.join(runtime, "shell", `${name}.js`)),
    ],
    { stdio: "inherit" },
  );
  const sections = RUNTIME_DTS_MODULES.map((name) => {
    const text = NodeFS.readFileSync(NodePath.join(out, "shell", `${name}.d.ts`), "utf8")
      // The page maps "three" to the runtime's copy; agents import it by that name.
      .replace(/"\.\.\/vendor\/three\.module\.js"/g, '"three"')
      .replace(/"\.\.\/vendor\/addons\//g, '"three/addons/')
      .replace(/^export \{\};\n?/gm, "")
      .trim();
    return `// ── ./shell/${name}.js ${"─".repeat(Math.max(4, 80 - name.length - 16))}\n\n${text}\n`;
  });
  const sources = RUNTIME_DTS_MODULES.map((name) =>
    NodeFS.readFileSync(NodePath.join(runtime, "shell", `${name}.js`), "utf8"),
  );
  const file = `// The runtime's API for a game's main.js: what each shell module it imports exports, with
// their documentation. Generated by scripts/runtime-dts.ts from the modules' JSDoc; never edit
// it by hand. What each module is for: studio-skills/runtime.md.
// sources ${runtimeDtsHash(sources)}

${sections.join("\n")}`;
  NodeFS.writeFileSync(NodePath.join(runtime, "runtime.d.ts"), file);
  console.log(`runtime.d.ts: ${Buffer.byteLength(file)} bytes, ${sections.length} modules`);
} finally {
  NodeFS.rmSync(out, { recursive: true, force: true });
}
